class Solution:
    def longestContinuousSubstring(self, s: str) -> int:
        best = cur = 1
        for i in range(1, len(s)):
            cur = cur + 1 if ord(s[i]) == ord(s[i - 1]) + 1 else 1
            best = max(best, cur)
        return best

