    int longestContinuousSubstring(string s) {
        int best = 1, cur = 1;
        for (int i = 1; i < (int)s.size(); i++) {
            cur = (s[i] == s[i - 1] + 1) ? cur + 1 : 1;
            best = max(best, cur);
        }
        return best;
    }
};

