class Solution:
    def longestContinuousSubstring(self, s: str) -> int:
        n = len(s)
        best = 1
        i = 0
        while i < n:
            j = i
            while j + 1 < n and ord(s[j + 1]) == ord(s[j]) + 1:
                j += 1
            best = max(best, j - i + 1)
            i = j + 1
        return best

